parameters.jsCode:
const body = $input.all()[0].json.body;
if (body.event !== 'conversation.ended') return [];
return [{ json: {
  conversationId: body.data.id,
  tenantId: body.data.tenantId,
  customerId: body.data.customerId,
  userId: body.data.userId,
  channel: body.data.channel || 'WEB_CHAT',
  messageCount: body.data.messageCount || 0,
  startedAt: body.data.startedAt,
  endedAt: body.data.endedAt
} }];

const aiRes = $('AI: Summarize Conversation').all()[0].json;
const data = aiRes.data || aiRes;
const ctx = $('Code: Prep Conversation').item.json;
const facts = data.facts || [];
const preferences = data.preferences || [];
// Combine facts + preferences into memory-save items
const memories = [
  ...facts.map(f => ({ type: 'FACT', key: f.key, value: f.value })),
  ...preferences.map(p => ({ type: 'PREFERENCE', key: p.key, value: p.value }))
];
return memories.map(m => ({
  json: {
    type: m.type,
    scope: 'CUSTOMER',
    entityId: ctx.customerId,
    tenantId: ctx.tenantId,
    key: m.key,
    value: m.value,
    conversationId: ctx.conversationId,
    workflow: 'conversation-summarization'
  }
}));

